#include "recovery_society_storage.hpp"
#include "flight_storage.hpp"
#include <stdexcept>
namespace hyperion {
using J=nlohmann::json;
namespace {
J vec(flight::V3 p){return J::array({p.x,p.y,p.z});}
double num(const J& j,const char* key,double low,double high,bool integral=false){double n=j.at(key).get<double>();if(!std::isfinite(n)||n<low||n>high||(integral&&std::floor(n)!=n))throw std::runtime_error(std::string("Invalid recovery society field: ")+key);return n;}
std::string str(const J& j,const char* key){auto s=j.at(key).get<std::string>();if(s.size()>512)throw std::runtime_error("Oversized recovery identity");return s;}
void list(const J& j,size_t max){if(!j.is_array()||j.size()>max)throw std::runtime_error("Oversized recovery collection");}
flight::V3 vector(const J& j){list(j,3);if(j.size()!=3)throw std::runtime_error("Invalid recovery position");flight::V3 v{j[0].get<double>(),j[1].get<double>(),j[2].get<double>()};if(!flight::finite(v)||flight::length(v)>1e7)throw std::runtime_error("Invalid recovery position");return v;}
Stock stock(const J& j){list(j,9);if(j.size()!=9)throw std::runtime_error("Invalid recovery manifest");Stock s{};for(int g=0;g<9;g++){s[g]=j[g].get<double>();if(!std::isfinite(s[g])||s[g]<0||s[g]>500)throw std::runtime_error("Invalid recovery manifest value");}return s;}
}
J encodeRecoverySociety(const Economy& e){
 J j={{"schema",1},{"crews",J::array()},{"boardings",J::array()},{"prizes",J::array()}};
 for(const auto& c:e.recoveryCrews){J path=J::array();for(auto p:c.route)path.push_back(vec(p));j["crews"].push_back({{"id",c.id},{"name",c.name},{"star",c.star},{"home",c.home},{"target",c.target},{"band",c.band},{"faction",c.faction},{"phase",c.phase},{"people",c.people},{"rescued",c.rescued},{"lastHour",c.lastHour},{"work",c.work},{"health",c.health},{"position",vec(c.position)},{"origin",vec(c.origin)},{"forward",vec(c.forward)},{"cargo",c.cargo},{"route",path},{"leg",c.leg}});}
 for(const auto& [id,b]:e.boardings)j["boardings"].push_back({{"id",id},{"star",b.star},{"home",b.home},{"band",b.band},{"prize",b.prize},{"faction",b.faction},{"status",b.status},{"rooms",b.rooms},{"initialParty",b.initialParty},{"party",b.party},{"partyLost",b.partyLost},{"partyReturned",b.partyReturned},{"initialDefenders",b.initialDefenders},{"defenders",b.defenders},{"defendersLost",b.defendersLost},{"defendersReturned",b.defendersReturned},{"reserve",b.reserve},{"surrendered",b.surrendered},{"crime",b.crime},{"started",b.started},{"updated",b.updated},{"seed",b.seed},{"cargo",b.cargo},{"initialCargo",b.initialCargo},{"looted",b.looted},{"transferred",b.transferred},{"destroyed",b.destroyed}});
 for(const auto& p:e.prizes){const auto& o=p.ship;j["prizes"].push_back({{"id",p.id},{"source",p.source},{"faction",p.faction},{"disputed",p.disputed},{"port",o.port},{"serial",o.vessel.serial},{"model",o.vessel.model},{"fitted",o.vessel.fitted},{"equipment",encodeCombatState(o.equipment)},{"hull",o.hull},{"fuel",o.fuel},{"tank",o.tank},{"shield",o.shield}});}return j;
}
void decodeRecoverySociety(Economy& e,const J& j,double hour){
 if(!j.is_object()||j.at("schema")!=1)throw std::runtime_error("Unsupported recovery society");list(j.at("crews"),512);list(j.at("boardings"),512);list(j.at("prizes"),64);std::set<std::string> ids;
 for(const auto& a:j.at("crews")){RecoveryCrew c;c.id=str(a,"id");c.name=str(a,"name");c.star=str(a,"star");c.home=str(a,"home");c.target=str(a,"target");c.band=str(a,"band");c.faction=int(num(a,"faction",1,4,true));c.phase=int(num(a,"phase",0,4,true));c.people=int(num(a,"people",0,2,true));c.rescued=int(num(a,"rescued",0,8,true));c.lastHour=num(a,"lastHour",0,hour+1e-7);c.work=num(a,"work",0,.500001);c.health=num(a,"health",0,100);c.position=vector(a.at("position"));c.origin=vector(a.at("origin"));c.forward=vector(a.at("forward"));c.cargo=stock(a.at("cargo"));list(a.at("route"),512);for(const auto& p:a.at("route"))c.route.push_back(vector(p));c.leg=int(num(a,"leg",0,c.route.size(),true));
  auto* home=findSettlement(e,c.home);if(c.id.empty()||!ids.insert(c.id).second||!e.systems.count(c.star)||!home||home->star!=c.star||std::abs(flight::length(c.forward)-1)>1e-5||stockTotal(c.cargo)>40.001||(c.phase>=3&&(c.people||c.rescued||stockTotal(c.cargo)>.00001))||(c.phase==4&&c.health>0)||(!c.band.empty()&&!findPirates(e,c.band)))throw std::runtime_error("Invalid recovery crew graph");e.recoveryCrews.push_back(c);
 }
 for(const auto& a:j.at("boardings")){Boarding b;b.id=str(a,"id");b.star=str(a,"star");b.home=str(a,"home");b.band=str(a,"band");b.prize=str(a,"prize");b.faction=int(num(a,"faction",0,4,true));b.status=int(num(a,"status",0,3,true));b.rooms=int(num(a,"rooms",0,7,true));b.initialParty=int(num(a,"initialParty",0,3,true));b.party=int(num(a,"party",0,3,true));b.partyLost=int(num(a,"partyLost",0,3,true));b.partyReturned=int(num(a,"partyReturned",0,3,true));b.initialDefenders=int(num(a,"initialDefenders",0,8,true));b.defenders=int(num(a,"defenders",0,8,true));b.defendersLost=int(num(a,"defendersLost",0,8,true));b.defendersReturned=int(num(a,"defendersReturned",0,8,true));b.reserve=a.at("reserve").get<bool>();b.surrendered=a.at("surrendered").get<bool>();b.crime=a.at("crime").get<bool>();b.started=num(a,"started",0,hour+1e-7);b.updated=num(a,"updated",b.started,hour+1e-7);b.seed=uint32_t(num(a,"seed",0,4294967295.,true));b.cargo=stock(a.at("cargo"));b.initialCargo=stock(a.at("initialCargo"));b.looted=stock(a.at("looted"));b.transferred=stock(a.at("transferred"));b.destroyed=stock(a.at("destroyed"));
  if(b.id.empty()||!e.systems.count(b.star)||(!b.home.empty()&&!findSettlement(e,b.home))||b.initialParty!=b.party+b.partyLost+b.partyReturned||b.initialDefenders!=b.defenders+b.defendersLost+b.defendersReturned||(b.status==0&&b.party==0)||(b.status!=0&&b.party!=0)||(b.surrendered&&b.rooms!=7)||!e.boardings.emplace(b.id,b).second)throw std::runtime_error("Invalid boarding population or identity");for(int g=0;g<goodCount;g++)if(std::abs(b.initialCargo[g]-b.cargo[g]-b.looted[g]-b.transferred[g]-b.destroyed[g])>1e-6)throw std::runtime_error("Boarding supplies not conserved");
 }
 ids={e.vessel.serial};for(const auto& o:e.shipOffers)ids.insert(o.vessel.serial);
 for(const auto& a:j.at("prizes")){PrizeShip p;p.id=str(a,"id");p.source=str(a,"source");p.faction=int(num(a,"faction",-1,4,true));p.disputed=a.at("disputed").get<bool>();auto& o=p.ship;o.port=str(a,"port");o.vessel.serial=str(a,"serial");o.vessel.model=int(num(a,"model",0,flight::vesselModelCount-1,true));const auto& fits=a.at("fitted");list(fits,flight::vesselUpgradeCount);if(fits.size()!=flight::vesselUpgradeCount)throw std::runtime_error("Invalid prize fittings");for(int i=0;i<flight::vesselUpgradeCount;i++){double v=fits[i].get<double>();if(!std::isfinite(v)||v<0||v>3||std::floor(v)!=v)throw std::runtime_error("Invalid prize fitting");o.vessel.fitted[i]=int(v);}o.equipment=decodeCombatState(a.at("equipment"));o.hull=num(a,"hull",0,100);o.tank=num(a,"tank",1,100000);o.fuel=num(a,"fuel",0,o.tank);o.shield=num(a,"shield",0,flight::shieldCapacity(o.vessel));
  if(p.id.empty()||p.id!=o.vessel.serial||!ids.insert(p.id).second||(p.disputed&&p.faction<=0)||(!o.port.empty()&&!findSettlement(e,o.port))||(o.port.empty()&&(!e.worldDamage.count(p.source)||!e.worldDamage.at(p.source).recovery.intact)))throw std::runtime_error("Invalid captured hull custody");e.prizes.push_back(p);
 }
}
void validateRecoverySociety(const Economy& e){
 std::map<std::string,int> aboard;int active=0,passengers=0,tows=0;for(const auto& c:e.recoveryCrews)if(c.phase<3)aboard[c.target]+=c.rescued;
 for(const auto& [id,d]:e.worldDamage){const auto& r=d.recovery;if(r.npcAboard!=aboard[id])throw std::runtime_error("Recovery passengers disagree with transport");passengers+=r.aboard;tows+=r.towed;}
 for(const auto& [id,b]:e.boardings){active+=b.status==0;if(b.status==2)passengers+=b.defenders;}for(const auto& w:e.oceanWrecks)passengers+=w.aboard;
 if(active>1||passengers>12||tows>1)throw std::runtime_error("Recovery berths, boarding parties or tow capacity exceeded");
 for(const auto& [id,n]:aboard)if(n&&!e.worldDamage.count(id))throw std::runtime_error("Transport passengers have no source wreck");
}
}
